insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000019000','Verifique a ideia','Que pergunta investiga uma experiência?','["Como você encontra o material?","Você aprova meu botão?","Meu desenho está bonito?"]'::jsonb,'Como você encontra o material?. Uma pergunta aberta pede um relato, por exemplo: Como você encontra os materiais da última aula? Ela permite descobrir caminhos e dificuldades sem impor uma resposta.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000015',40) on conflict(id) do nothing;
