insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000019004','Verifique a ideia','Qual elemento ajuda a localizar um material?','["Busca com rótulo claro","Texto sem identificação","Somente decoração"]'::jsonb,'Busca com rótulo claro. Agrupe itens relacionados: a busca perto da lista filtrada e os materiais dentro da matéria correspondente. Um grupo ajuda a prever onde procurar.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000015',40) on conflict(id) do nothing;
