insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000019005','Verifique a ideia','Onde colocar itens da mesma matéria?','["No mesmo grupo","Em locais aleatórios","Fora da lista"]'::jsonb,'No mesmo grupo. A hierarquia indica prioridade. O título identifica a tela; a busca recebe destaque se encontrar material for a tarefa principal.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000015',40) on conflict(id) do nothing;
