insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000019007','Verifique a ideia','Por que manter um rótulo visível?','["Para identificar o campo durante a digitação","Para substituir o conteúdo","Para esconder a busca"]'::jsonb,'Para identificar o campo durante a digitação. Percorra o desenho como estudante: encontre a matéria, selecione um material e confirme onde está. Anote qualquer passo ambíguo para o teste seguinte.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000015',40) on conflict(id) do nothing;
