insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000019008','Verifique a ideia','Qual é uma tarefa concreta?','["Encontrar a última aula de Biologia","Dizer se a tela é bonita","Aprovar o designer"]'::jsonb,'Encontrar a última aula de Biologia. Antes da sessão, defina sucesso observável: abrir o material correto sem ajuda. Registre também tempo aproximado e hesitações, sem inventar um limite universal.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000015',40) on conflict(id) do nothing;
