insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000019009','Verifique a ideia','O que observar?','["Cliques e hesitações","Somente a intenção declarada","A resposta sugerida pelo mediador"]'::jsonb,'Cliques e hesitações. Durante a tarefa, não aponte o botão nem ensine o caminho. Observe cliques, erros e comentários da pessoa.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000015',40) on conflict(id) do nothing;
