insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000019010','Verifique a ideia','Quando ajudar com o caminho?','["Depois de registrar a dificuldade","A cada clique","Antes da tentativa"]'::jsonb,'Depois de registrar a dificuldade. Depois, pergunte o que causou dúvida. Uma hesitação observada é evidência; sua hipótese sobre a causa precisa ser verificada.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000015',40) on conflict(id) do nothing;
