insert into public.lesson_plans(module_id,level,question_ids,dynamic,resource_ids,pedagogy) values('00000000-0000-4000-8000-000000000305',2,array['00000000-0000-4000-8000-000000013025','00000000-0000-4000-8000-000000013026','00000000-0000-4000-8000-000000013027','00000000-0000-4000-8000-000000013028','00000000-0000-4000-8000-000000013029']::uuid[],'{"kind":"applied","title":"Faça um rastreamento","prompt":"Planeje um laço que soma os inteiros de 1 a 4. Mostre contador e soma após cada execução, explique como o laço termina e compare o resultado usando < e <= no limite escolhido.","criteria":["Mostrei o estado em cada execução","Expliquei a atualização e o término","Comparei as fronteiras e os totais esperados"],"minLength":240}'::jsonb,array['dart-loops']::text[],'{"concepts":["repetição","contador","acumulador"],"requires":["condicionais","variáveis"],"competency":"Aplicação guiada","prerequisite_ids":["00000000-0000-4000-8000-000000000304"],"version":2}'::jsonb) on conflict(module_id) do update set level=excluded.level,question_ids=excluded.question_ids,dynamic=excluded.dynamic,resource_ids=excluded.resource_ids,pedagogy=excluded.pedagogy;
insert into public.lesson_plans(module_id,level,question_ids,dynamic,resource_ids,pedagogy) values('00000000-0000-4000-8000-000000000306',2,array['00000000-0000-4000-8000-000000013030','00000000-0000-4000-8000-000000013031','00000000-0000-4000-8000-000000013032','00000000-0000-4000-8000-000000013033','00000000-0000-4000-8000-000000013034']::uuid[],'{"kind":"creation","title":"Projete uma função de resumo","prompt":"Descreva uma função que recebe uma lista de notas e devolve quantidade, soma e média. Defina explicitamente o retorno para lista vazia e teste [], [6] e [7, 8, 9], sem inventar uma média para o caso vazio.","criteria":["Tratei o vazio antes de acessar ou dividir","Defini os três campos de saída","Calculei os resultados dos três testes"],"minLength":260}'::jsonb,array['dart-collections']::text[],'{"concepts":["listas","índice","lista vazia"],"requires":["repetição","acumulador"],"competency":"Aplicação guiada","prerequisite_ids":["00000000-0000-4000-8000-000000000305"],"version":2}'::jsonb) on conflict(module_id) do update set level=excluded.level,question_ids=excluded.question_ids,dynamic=excluded.dynamic,resource_ids=excluded.resource_ids,pedagogy=excluded.pedagogy;
